exports.formato = function formato(n) {
  // TODO: esto se podría simplificar
  var s = '' + n;
  var partes = s.split('.');
  if (partes.length == 1) { return s + '.00'; }
  if (partes[1].length == 1) { return s + '0'; }
  return partes[0] + '.' + partes[1].substring(0, 2);
};

